func federatedSourceProof(files Files, source Store, identity ArtifactRef, pinnedRevision string) (string, string, string, string, []string, []FederatedDependencyEvidence, []string) {
	scope := localFederatedScope(identity)
	state, err := source.GetCloseoutState(scope)
	if err != nil || !state.Terminal {
		return "", "", "", "", nil, nil, []string{scope + ":source-closeout-not-terminal"}
	}
	// A milestone or roadmap the source closed without its own review, under
	// its adopted closeout review policy, is proven by the receipt of that
	// close: the source's policy decides, never the consumer's. Its members
	// are federated with their own reviews (spec
	// pose-closeout-review-policy-by-cost-benefit).
	if receipt := state.CloseoutReceipt; receipt != nil && !receipt.Decision.Required && (identity.Kind == "milestone" || identity.Kind == "roadmap") {
		raw, err := json.Marshal(receipt)
		if err != nil {
			return "", "", "", "", nil, nil, []string{scope + ":source-closeout-receipt-unreadable"}
		}
		return "closeout-receipt:" + scope, "sha256:" + digestHex(raw), receipt.SubjectDigest, receipt.PolicyDigest, nil, nil, nil
	}
	verification, err := source.VerifyReviewBundle(scope)
	// A milestone its roadmap declares has no review of its own: what a consumer can
	// hold is the review of that roadmap, which sealed the declaration.
	if err == nil && identity.Kind == "milestone" && strings.HasPrefix(verification.ApprovalOrigin, "declared:") {
		verification, err = source.VerifyReviewBundle("roadmap:" + identity.Slug)
	}
	if err != nil || !verification.Fresh || !verification.Approved || verification.Bundle == nil || verification.Attestation == nil || !source.sealedDeclarationHolds(verification.Bundle) {
		return "", "", "", "", nil, nil, []string{scope + ":source-review-not-approved"}
	}
	bundle := verification.Bundle
	eligible := federatedSourceEvidenceEligibilityIn(files, source.Root, pinnedRevision, bundle.Payload.Subject.Head)
	if identity.Kind == "spec" {
		spec, err := source.GetSpec(identity.Slug)
		if err != nil {
			return "", "", "", "", nil, nil, []string{scope + ":unavailable-artifact"}
		}
		targets, _, err := ParseDeliveryTargets(*spec)
		if err != nil || len(targets) == 0 {
			return bundle.BundleID, bundle.BundleDigest, bundle.Payload.Subject.ImplementationDigest, bundle.Payload.Plan.PlanDigest, bundle.Payload.GoverningContracts, nil, []string{scope + ":source-delivery-target-missing"}
		}

