				reason, state = resolved.State, resolved.State
			} else if graphReason := resolver.ValidateGraph(project, raw); graphReason != "" {
				reason, graph = graphReason, graphReason
			} else if resolved.Status != "done" {
				notDone = true
				reason = fmt.Sprintf("%s status is %q (needs done)", ref.Kind, resolved.Status)
				if ref.Kind == "milestone" && ref.Project == "" {
					reason = s.milestoneWaitingReason(ref.Slug + "/" + ref.Milestone)
				}
			}
		}
		if reason != "" {
			r.WaitingOn = append(r.WaitingOn, WaitingRef{Ref: raw, Reason: reason, Code: dependencyWaitingCode(state, graph, notDone), Detail: firstNonempty(state, graph)})
		}
	}

	if blocked {
		dependencies := 0
		for _, waiting := range r.WaitingOn {
			if !strings.HasPrefix(waiting.Ref, "dor:") {
				dependencies++
			}
		}
		if dependencies > 0 {
			r.Cause = ReadinessCauseDependency
			r.Reason = fmt.Sprintf("spec is blocked (an operational condition, not a terminal status) and waits on %d unsatisfied dependency(ies)", dependencies)
		} else {
			r.Cause = ReadinessCauseUnknown
			r.Reason = "spec is blocked (an operational condition, not a terminal status) and no recorded cause explains it"
		}
		return r, nil
	}
	r.Ready = len(r.WaitingOn) == 0
	if !r.Ready && r.Reason == "" {
		r.Reason = fmt.Sprintf("%d unsatisfied dependency(ies)", len(r.WaitingOn))

}

// nextCloses names what the close of a scope leaves reachable: the milestones a
// spec finished, or the roadmap a milestone finished (spec
// pose-milestone-closes-when-reached R3). A failed read is reported in its place,
// since the close itself stands.
func nextCloses(store posemodel.Store, ref string) []string {
	scope, err := posemodel.ParseScopeRef(ref)
	if err != nil {
		return nil
	}
	next := []string{}
	switch scope.Kind {
	case "spec":
		reached, err := store.ReachedMilestones(scope.Slug)
		if err != nil {
			return []string{"unavailable: " + err.Error()}
		}
		for _, milestone := range reached {
			next = append(next, "pose close "+milestone)
		}
		roadmaps, err := store.RoadmapsReachedBy(scope.Slug)
		if err != nil {
			return []string{"unavailable: " + err.Error()}
		}
		for _, roadmap := range roadmaps {
			next = append(next, "pose close roadmap:"+roadmap)
		}
	case "milestone":
		if store.RoadmapReached(scope.Roadmap) {
			next = append(next, "pose close roadmap:"+scope.Roadmap)
		}
	}
	return next
}

func renderCloseNext(out *cliout.Renderer, next []string) {
	for _, step := range next {
		out.Field("close.next", step)
	}
}

